"use client"

import type * as React from "react"

import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import {
  AgentIcon,
  CallerIcon,
  ExpandIcon,
  HumanAgentIcon,
  ToolFailedIcon,
  ToolIcon,
} from "@/components/mockups/tool-calls-transcript/icons"
import type {
  TranscriptMessage,
  TranscriptRole,
} from "@/lib/mockups/tool-calls-transcript-data"
import { cn } from "@/lib/utils"

/**
 * The call transcript with tool calls — DES-205.
 *
 * The speech is drawn the way the reviewed call drawer draws it
 * (`/conversations-revamp`): a tinted avatar, a bubble with the speaker and the
 * time into the call on its first line. The design system has no transcript
 * pattern of its own yet, so that drawer is the reference.
 *
 * A call and its result are one row. They arrive as two items linked by
 * `toolCallId`, often with speech between them, and as two pills the reader
 * had to match them up by eye. The row sits where the call was made and
 * carries its result, so whatever was said while the tool ran reads after it.
 *
 * There is no success state. The UI only knows `isError`; everything else —
 * a connected transfer, an instruction to retry, an empty output — is the tool
 * returning, and what it returned is printed on the row. Only a failure gets
 * colour, an icon of its own and the word "Failed", so it cannot be read as
 * anything else, in colour or without it.
 */

type Call = Extract<TranscriptMessage, { type: "function_call" }>
type Result = Extract<TranscriptMessage, { type: "function_call_output" }>
type Speech = Extract<TranscriptMessage, { type: "message" }>
type Json = null | boolean | number | string | Json[] | { [key: string]: Json }

type Row =
  | { kind: "speech"; key: string; message: Speech }
  | { kind: "tool"; key: string; call?: Call; result?: Result }

/**
 * Folds each result into its call's row. A result whose call is missing still
 * gets a row of its own where it landed, so nothing the agent recorded drops
 * off the transcript.
 */
function toRows(messages: TranscriptMessage[]): Row[] {
  const rows: Row[] = []
  const tools = new Map<string, Extract<Row, { kind: "tool" }>>()

  messages.forEach((message, index) => {
    if (message.type === "message") {
      rows.push({ kind: "speech", key: `m${index}`, message })
      return
    }

    const existing = tools.get(message.toolCallId)
    if (message.type === "function_call_output" && existing) {
      existing.result = message
      return
    }

    const row: Extract<Row, { kind: "tool" }> =
      message.type === "function_call"
        ? { kind: "tool", key: message.toolCallId, call: message }
        : { kind: "tool", key: message.toolCallId, result: message }
    tools.set(message.toolCallId, row)
    rows.push(row)
  })

  return rows
}

export function CallTranscript({
  messages,
  startedAt,
}: {
  messages: TranscriptMessage[]
  startedAt: number
}) {
  return (
    <div className="flex flex-col gap-4">
      {toRows(messages).map((row) =>
        row.kind === "speech" ? (
          <SpeechTurn
            key={row.key}
            message={row.message}
            startedAt={startedAt}
          />
        ) : (
          <ToolRow
            call={row.call}
            key={row.key}
            result={row.result}
            startedAt={startedAt}
          />
        ),
      )}
    </div>
  )
}

/* ------------------------------------------------------------------ speech */

const SPEAKERS: Record<
  TranscriptRole,
  { icon: React.ReactNode; label: string; isCaller: boolean }
> = {
  assistant: {
    icon: <AgentIcon className="size-4" />,
    label: "Agent",
    isCaller: false,
  },
  user: {
    icon: <CallerIcon className="size-4" />,
    label: "Customer",
    isCaller: true,
  },
  "human agent": {
    icon: <HumanAgentIcon className="size-4" />,
    label: "Human agent",
    isCaller: false,
  },
}

function SpeakerAvatar({
  isCaller,
  icon,
}: {
  isCaller: boolean
  icon: React.ReactNode
}) {
  return (
    <span
      className={cn(
        "flex size-8 shrink-0 items-center justify-center rounded-4xl",
        isCaller ? "bg-muted text-foreground" : "bg-primary/10 text-primary",
      )}
    >
      {icon}
    </span>
  )
}

function SpeechTurn({
  message,
  startedAt,
}: {
  message: Speech
  startedAt: number
}) {
  const speaker = SPEAKERS[message.role]

  return (
    <div className={cn("flex gap-3", speaker.isCaller && "flex-row-reverse")}>
      <SpeakerAvatar icon={speaker.icon} isCaller={speaker.isCaller} />
      <div
        className={cn(
          "flex max-w-[80%] flex-col gap-1 rounded-lg px-4 py-2.5",
          speaker.isCaller
            ? "bg-primary text-primary-foreground"
            : "bg-muted text-foreground",
        )}
      >
        {/* The call is usually Arabic and the UI English: each line picks its
            own direction from its first strong character. */}
        <p className="text-sm" dir="auto">
          {message.content}
        </p>
        {/* What was said leads; who and when sit under it, because the side,
            the avatar and the colour already say who. */}
        <span className="flex items-center gap-4 text-xs opacity-70">
          <span className="font-medium">{speaker.label}</span>
          <span className="ms-auto tabular-nums">
            {formatOffset(message.startAt, startedAt)}
          </span>
        </span>
      </div>
    </div>
  )
}

/* -------------------------------------------------------------------- tool */

/** The first line of what the tool returned, or why there is nothing to show. */
function summary(call?: Call, result?: Result) {
  if (!result) return call ? "No result recorded" : ""
  if (result.output.trim() === "") return "No output"
  return result.output.split("\n")[0] ?? ""
}

/** 640 ms · 4.2 s · 1 min 12 s. Never "0 ms" for a duration nobody measured. */
function formatDuration(ms: number | null | undefined) {
  if (ms === null || ms === undefined) return null
  if (ms < 1000) return `${Math.round(ms)} ms`
  if (ms < 60_000) return `${(ms / 1000).toFixed(1)} s`
  const seconds = Math.round(ms / 1000)
  return `${Math.floor(seconds / 60)} min ${seconds % 60} s`
}

/** Time into the call, as the recording player counts it. */
function formatOffset(at: number, startedAt: number) {
  const seconds = Math.max(0, Math.round(at - startedAt))
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`
}

function parseJson(text: string): Json | null {
  const trimmed = text.trim()
  if (!trimmed.startsWith("{") && !trimmed.startsWith("[")) return null
  try {
    return JSON.parse(trimmed) as Json
  } catch {
    return null
  }
}

function isEmptyArguments(value: string) {
  const json = parseJson(value)
  return (
    value.trim() === "" ||
    (json !== null &&
      typeof json === "object" &&
      Object.keys(json).length === 0)
  )
}

function ToolRow({
  call,
  result,
  startedAt,
}: {
  call?: Call
  result?: Result
  startedAt: number
}) {
  const toolName = call?.toolName ?? result?.toolName ?? ""
  const failed = result?.isError === true
  const duration = formatDuration(result?.durationMs)
  const calledAt = call?.startAt ?? result?.startAt
  const hasArguments = call !== undefined && !isEmptyArguments(call.arguments)
  const output = result?.output.trim() ?? ""

  /* Every row with something in it opens, so the chevron means the same on
     every row. The summary line stays put while open — hiding it made the
     header jump while the body animated — so a one-line output shows twice
     when open, which is the lesser cost. Only an empty row stays shut. */
  const showOutput = output !== ""
  const canOpen = hasArguments || showOutput

  const header = (
    <>
      <span
        className={cn(
          "flex h-4 shrink-0 items-center [&_svg]:size-4",
          failed ? "text-destructive" : "text-muted-foreground",
        )}
      >
        {failed ? <ToolFailedIcon /> : <ToolIcon />}
      </span>
      <span className="flex min-w-0 flex-1 flex-col gap-0.5">
        <span className="flex items-center gap-2">
          <span className="font-mono font-medium text-foreground" dir="ltr">
            {toolName}
          </span>
          {failed ? (
            <span className="font-medium text-destructive">Failed</span>
          ) : null}
          <span className="ms-auto flex items-center gap-3 text-muted-foreground tabular-nums">
            {duration ? <span>{duration}</span> : null}
            {calledAt !== undefined ? (
              <span>{formatOffset(calledAt, startedAt)}</span>
            ) : null}
          </span>
        </span>
        {/* Output is English written for the model; pin it left-to-right so
            an Arabic page does not reorder its punctuation. */}
        <span className="truncate text-muted-foreground" dir="ltr">
          {summary(call, result)}
        </span>
      </span>
    </>
  )

  const surface = cn(
    "ms-11 rounded-lg",
    failed ? "bg-destructive/10" : "bg-muted",
  )

  if (!canOpen) {
    return (
      <div className={surface}>
        <div className="flex items-start gap-2 px-3 py-2 text-xs">
          {header}
          {/* Holds the chevron's column so every row's numbers line up. */}
          <span className="size-4 shrink-0" />
        </div>
      </div>
    )
  }

  return (
    <Collapsible className={surface}>
      <CollapsibleTrigger className="group/tool flex w-full items-start gap-2 rounded-lg px-3 py-2 text-start text-xs outline-none focus-visible:ring-3 focus-visible:ring-ring/50">
        {header}
        <span className="flex h-4 shrink-0 items-center text-muted-foreground [&_svg]:size-4">
          <ExpandIcon className="transition-transform duration-150 ease-out-cubic group-data-[state=open]/tool:rotate-180 motion-reduce:transition-none" />
        </span>
      </CollapsibleTrigger>

      <CollapsibleContent className="overflow-hidden data-[state=closed]:animate-collapsible-up data-[state=open]:animate-collapsible-down motion-reduce:animate-none">
        <div className="flex flex-col gap-3 px-3 pt-1 pb-3">
          {hasArguments ? (
            <Payload label="Arguments" value={call.arguments} />
          ) : null}
          {showOutput ? <Payload label="Output" value={output} /> : null}
        </div>
      </CollapsibleContent>
    </Collapsible>
  )
}

/**
 * What went to the tool or came back, verbatim, in monospace — so it reads as
 * "this is what the model saw", not as page copy. JSON is pretty-printed into
 * the same block. No border: the white block on the row's tint is the edge.
 */
function Payload({ label, value }: { label: string; value: string }) {
  const json = parseJson(value)

  return (
    <div className="flex flex-col gap-1.5">
      <span className="text-xs font-medium text-muted-foreground">{label}</span>
      <pre
        className="max-h-64 overflow-auto rounded-lg bg-background px-3 py-2.5 font-mono text-xs leading-relaxed whitespace-pre-wrap text-foreground"
        dir="ltr"
      >
        {json !== null ? JSON.stringify(json, null, 2) : value}
      </pre>
    </div>
  )
}

"use client"

import {
  ArrowDown01Icon,
  BotIcon,
  CancelCircleIcon,
  HeadsetIcon,
  UserIcon,
  Wrench01Icon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/shared/icon"

/* Who is speaking — the same three glyphs the call page uses today. */
export const AgentIcon = icon(BotIcon, "AgentIcon")
export const CallerIcon = icon(UserIcon, "CallerIcon")
export const HumanAgentIcon = icon(HeadsetIcon, "HumanAgentIcon")

/* A tool row: a tool ran, or a tool failed. There is no success glyph. */
export const ToolIcon = icon(Wrench01Icon, "ToolIcon")
export const ToolFailedIcon = icon(CancelCircleIcon, "ToolFailedIcon")

export const ExpandIcon = icon(ArrowDown01Icon, "ExpandIcon")

"use client"

import {
  ArrowLeft02Icon,
  ArrowRight02Icon,
  ArrowUp01Icon,
  ArrowUpRight01Icon,
  BookOpen01Icon,
  Cancel01Icon,
  Copy01Icon,
  Cursor02Icon,
  Link04Icon,
  Search01Icon,
  SourceCodeIcon,
  Tick02Icon,
  TranslateIcon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/shared/icon"

/**
 * Icons for the workspace itself — the index and the shell around every
 * mockup. Icons *inside* a mockup live in that mockup's own icons.tsx; this
 * file is only the chrome.
 */
export const BackIcon = icon(ArrowLeft02Icon, "BackIcon")
export const OpenIcon = icon(ArrowRight02Icon, "OpenIcon")
export const SearchIcon = icon(Search01Icon, "SearchIcon")
export const ClearIcon = icon(Cancel01Icon, "ClearIcon")
export const DirectionIcon = icon(TranslateIcon, "DirectionIcon")

/* Beside the ticket ID in a card's footer, so it reads as something that
   leaves the page rather than as another in-page action. */
export const TicketLinkIcon = icon(ArrowUpRight01Icon, "TicketLinkIcon")

/* On the dock at the foot of the index, pointing at the list of surfaces
   that opens above it. */
export const DockIcon = icon(ArrowUp01Icon, "DockIcon")

/* The registry menu on an index card: the trigger, and the copy affordance
   that swaps to a tick once the command is on the clipboard. */
export const RegistryIcon = icon(SourceCodeIcon, "RegistryIcon")
export const CopyIcon = icon(Copy01Icon, "CopyIcon")
export const CopiedIcon = icon(Tick02Icon, "CopiedIcon")

/* On the index header, next to the search field — the way into the design
   system, which has no card in the list below. */
export const RulesIcon = icon(BookOpen01Icon, "RulesIcon")

/* Opens the card's links — the mockup's own URL and the tickets it answers —
   for copying rather than for following. */
export const ShareLinkIcon = icon(Link04Icon, "ShareLinkIcon")

/* The coach. It labels the nav button that replays the walkthrough, and it is
   the glyph the walkthrough parks on whatever control the reader is meant to
   press — the one place in the lab where an icon stands in for a pointer,
   because the pointer is what it is talking about. */
export const PointerIcon = icon(Cursor02Icon, "PointerIcon")

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
